# Fetch eye study 2 (the human-like direction). URLs byte-for-byte.
$ErrorActionPreference = 'Stop'
$dest = 'E:\AI\style-dataset-lab\projects\ferrochrome\outputs\candidates\eye-study-2'
New-Item -ItemType Directory -Force -Path $dest | Out-Null

$items = @(
  @{ name = 'a_full_human.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/16c8a09620b2e23609215239bab0168efeb1a1c94e060661be1cf9537efc4cd7.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T005137Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_eyes2_a_full_human_00001_.png%22' }
  @{ name = 'b_no_hair.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/5af9b15392bca535c0d0e6cde14d8f3c2ba6a55720eb67f314e79d7bcfc5006c.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T005137Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_eyes2_b_no_hair_00001_.png%22' }
  @{ name = 'c_hairline_tell.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/d92d0629479cb2256df50418bea45212be7bf0a3c7d34fab0b45677f7cb85513.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T005137Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_eyes2_c_hairline_tell_00001_.png%22' }
  @{ name = 'd_soft_gaze.png'
     url  = 'https://storage.googleapis.com/comfy-cloud-assets/5caef628c417bdac381795270abe92df325bf312cef5806a00f7cdbf9dd8c168.png?X-Goog-Algorithm=GOOG4-RSA-SHA256&X-Goog-Credential=comfy-cloud-prod-workload-sa%40comfy-cloud-prod.iam.gserviceaccount.com%2F20260823%2Fauto%2Fstorage%2Fgoog4_request&X-Goog-Date=20260823T005137Z&X-Goog-Expires=21599&X-Goog-&X-Goog-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%3D%22ferrochrome_eyes2_d_soft_gaze_00001_.png%22' }
)

foreach ($i in $items) {
  $out = Join-Path $dest $i.name
  curl.exe -L --fail-with-body --retry 3 --retry-all-errors --connect-timeout 20 -s -o $out -- $i.url
  if ($LASTEXITCODE -ne 0) { throw "download failed for $($i.name) (curl exit $LASTEXITCODE)" }
  Write-Output ("{0}  {1:N0} bytes" -f $i.name, (Get-Item $out).Length)
}
